-- Written to be re-runnable: production applies each statement on its own, so a run
-- interrupted part way must be able to start again from the top.
-- Invitation decline (DECL1): the invited person can say no on the accept screen of a sharing,
-- client, contributor or agency invitation. Adds the DECLINED status to the three invitation
-- enums and lets the sharing invitation check allow it. Additive, nothing existing is changed, no
-- backfill. Generated by drizzle-kit and made re-runnable here. Until this runs the code finds the
-- value missing and does not offer Decline.
ALTER TYPE "public"."client_invitation_status" ADD VALUE IF NOT EXISTS 'DECLINED';--> statement-breakpoint
ALTER TYPE "public"."contributor_request_status" ADD VALUE IF NOT EXISTS 'DECLINED';--> statement-breakpoint
ALTER TYPE "public"."organization_invitation_status" ADD VALUE IF NOT EXISTS 'DECLINED';--> statement-breakpoint
ALTER TABLE "sharing_invitations" DROP CONSTRAINT IF EXISTS "sharing_invitations_status_check";--> statement-breakpoint
ALTER TABLE "sharing_invitations" ADD CONSTRAINT "sharing_invitations_status_check" CHECK ("sharing_invitations"."status" in ('PENDING', 'ACCEPTED', 'REVOKED', 'DECLINED'));
